begin;
select plan(20);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values('a3333333-3333-4333-8333-333333333333','00000000-0000-0000-0000-000000000000','authenticated','authenticated','part3-context@example.test','',now(),now());
create temporary table context_setup(payload jsonb);
insert into context_setup values('{"profile":{"intent":"unanswered","primaryGoal":{"state":"withheld"},"secondaryGoals":[],"skinBehavior":"unanswered","reactivity":"generally_tolerates","reproductive":{"pregnancy":"unanswered","tryingToConceive":"withheld","nursing":"unsure"},"sensitivities":{"status":"none_known","values":[]},"treatments":{"status":"none","values":[]}},"routine":{"completeness":"partial","items":[]},"experiences":[{"id":"a3333333-3333-4333-8333-333333333334","reference":{"kind":"manual","name":"Old synthetic cream"},"kind":"reacted","occurred":{"start":{"state":"unanswered"},"end":{"state":"unanswered"}},"useContext":null,"symptoms":["Stinging"],"note":"Original synthetic report"}],"preferences":[],"assessments":[],"notes":[{"id":"a3333333-3333-4333-8333-333333333335","scope":"profile","targetRef":null,"text":"Synthetic private note"}],"setupAnswers":{"currentProducts":"unanswered","pastProducts":"reported"}}');
select ok(not has_function_privilege('authenticated','public.save_personal_context_setup(uuid,uuid,bigint,jsonb)','EXECUTE'),'Clients cannot bypass Edge setup validation');
select ok(not has_function_privilege('anon','public.read_personal_context_v2(uuid)','EXECUTE'),'Anonymous cannot read private context');
select ok(not has_table_privilege('authenticated','private.personal_context_erased_requests','SELECT,INSERT,UPDATE,DELETE'),'Request tombstones are private');
select is(public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333336',0,(select payload from context_setup))->>'contextRevision','1','Setup commits one context revision');
select is((select count(*)::int from public.personal_context_revisions where user_id='a3333333-3333-4333-8333-333333333333'),1,'Setup is one atomic aggregate');
select is(public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333336',0,(select payload from context_setup))->>'replayed','true','Exact setup retry is idempotent');
select throws_ok($$select public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333336',0,jsonb_set((select payload from context_setup),'{profile,primaryGoal}','{"state":"unsure"}'))$$,'P0001','IDEMPOTENCY_CONFLICT','Changed retry cannot overwrite');
select throws_ok($$select public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333337',0,(select payload from context_setup))$$,'P0001','STALE_CONTEXT','Concurrent stale setup conflicts');
select is(public.read_personal_context_v2('a3333333-3333-4333-8333-333333333333')->'setupRevision'->'data'->'profile'->'primaryGoal'->>'state','withheld','Withheld is not fabricated null or no');
select is(public.read_personal_experience_history_v2('a3333333-3333-4333-8333-333333333333',1,50,null,null,'Old synthetic cream')->'items'->0->'data'->>'kind','reacted','Scoped history includes setup reports');
select is(public.write_personal_context('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333338',1,'experience','{"id":"a3333333-3333-4333-8333-333333333334","reference":{"kind":"manual","name":"Old synthetic cream"},"kind":"no_reaction_reported","occurred":{"start":null,"end":null},"useContext":null,"symptoms":[],"note":"Corrected synthetic report"}',null)->'revision'->>'revision','2','Legacy editor correction advances shared head');
select is(jsonb_array_length(public.read_personal_experience_history_v2('a3333333-3333-4333-8333-333333333333',2)->'items'),1,'Correction is one active report');
select is(public.read_personal_experience_history_v2('a3333333-3333-4333-8333-333333333333',2)->'items'->0->'data'->>'kind','no_reaction_reported','Correction retains literal meaning');
select is(public.delete_personal_context_record('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333339',2,'experience','a3333333-3333-4333-8333-333333333334')->>'contextRevision','3','Erasure advances context revision');
select is((select count(*)::int from public.personal_context_revisions where user_id='a3333333-3333-4333-8333-333333333333' and payload::text like '%synthetic report%'),0,'Original and corrected v1/v2 report payloads are physically erased');
select is(public.delete_personal_context_record('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333339',2,'experience','a3333333-3333-4333-8333-333333333334')->>'replayed','true','Erasure retry is idempotent');
select throws_ok($$select public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333336',0,(select payload from context_setup))$$,'P0001','CONTEXT_REQUEST_ERASED','Retry cannot resurrect original report');
select is(public.delete_personal_context_record('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333340',3,'note','a3333333-3333-4333-8333-333333333335')->>'contextRevision','4','Note erasure advances context revision');
select is((select count(*)::int from public.personal_context_revisions where user_id='a3333333-3333-4333-8333-333333333333' and payload::text like '%Synthetic private note%'),0,'Original private note payload is erased');
update public.profiles set deletion_started_at=now() where id='a3333333-3333-4333-8333-333333333333';
select throws_ok($$select public.save_personal_context_setup('a3333333-3333-4333-8333-333333333333','a3333333-3333-4333-8333-333333333341',4,(select payload from context_setup))$$,'42501','CONTEXT_OWNER_UNAVAILABLE','Account erasure blocks late setup writes');
select * from finish();
rollback;
